{"implementation":"def solve(case):
    nodes = case["nodes"]
    core_dist = case["core_distance"]
    distances = case["distances"]
    n = len(nodes)
    mutual = {}
    for a, b, d in distances:
        key = tuple(sorted((a, b)))
        mr = max(core_dist[a], core_dist[b], d)
        mutual[key] = mr
    edges = []
    for (a,b), w in mutual.items():
        edges.append((w, a, b))
    edges.sort()
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, a, b in edges:
        if union(a, b):
            mst_edges.append((a, b, w))
            total_weight += w
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected")
    edges_list = [{"node1": a, "node2": b, "weight": w} for a, b, w in mst_edges]
    return {"edges": edges_list, "total_weight": total_weight}"}
